insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$The other sanctuaries are Panidihing Bird Sanctuary, Bherjan-Borajan-Padumoni, Nambor, Nambor-Doigrung and East Karbi Anglong.$t$ from public.content where slug = $t$wildlife-sanctuaries-of-assam$t$ on conflict do nothing;
