insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 7, 'paragraph', 'verified_fact', $t$Deepor Beel, a large {{term:wetland}} on the edge of Guwahati, is Assam's {{term:ramsar-site|Ramsar site}}. It was listed on 19 August 2002 and covers about 30 sq km.$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 8, 'paragraph', 'normal', $t$Beels (wetlands) across Assam give food, fish and homes to many birds, and help to hold flood water.$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
