insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 7, 'paragraph', 'verified_fact', $t$গুৱাহাটীৰ দাঁতিত থকা বৃহৎ {{term:wetland|জলাভূমি}} দীপৰ বিল অসমৰ {{term:ramsar-site|ৰামচাৰ ক্ষেত্ৰ}}। ২০০২ চনৰ ১৯ আগষ্টত ইয়াক তালিকাভুক্ত কৰা হয় আৰু ইয়াৰ আয়তন প্ৰায় ৩০ বৰ্গ কিমি।$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 8, 'paragraph', 'normal', $t$অসমৰ বিলসমূহে বহুতো চৰাইক খাদ্য, মাছ আৰু বাসস্থান দিয়ে, আৰু বানপানী ধৰি ৰাখাত সহায় কৰে।$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
